from core.prompts.domain_function_library import FractionOps, PolynomialOps, RadicalOps
from core.skill_policies.radical_logic import RadicalLogicEngine

def generate(level=1, **kwargs):
    radicand = 112

    simplified_coefficient, square_free_radicand = RadicalOps.simplify_term(radicand)

    question_text = f"Rewrite {simplified_coefficient} * sqrt({radicand}) in simplest radical form as coefficient * sqrt(square-free radicand)."

    correct_answer = {
        "coefficient": simplified_coefficient,
        "radicand": square_free_radicand
    }

    oracle_payload = {"radicand": 112}

    return {
        "question_text": question_text,
        "correct_answer": correct_answer,
        "oracle_payload": oracle_payload
    }

